import { useState, useEffect, useCallback } from 'react';
import apiService from '../services/api';

export function usePaginatedData(apiCall, initialPage = 1, initialLimit = 10) {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [pagination, setPagination] = useState({
    page: initialPage,
    limit: initialLimit,
    total: 0,
    totalPages: 0,
    hasNext: false,
    hasPrev: false
  });

  const loadData = useCallback(async (page = pagination.page, limit = pagination.limit) => {
    setLoading(true);
    setError('');

    try {
      const result = await apiCall(page, limit);

      // Verifica se o resultado tem paginação ou é array direto (compatibilidade)
      if (result.data && result.pagination) {
        // Formato paginado
        setData(result.data);
        setPagination(result.pagination);
      } else {
        // Formato array direto (sem paginação)
        setData(Array.isArray(result) ? result : []);
        setPagination({
          page: 1,
          limit: result.length || 0,
          total: result.length || 0,
          totalPages: 1,
          hasNext: false,
          hasPrev: false
        });
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Erro ao carregar dados');
      setData([]);
    } finally {
      setLoading(false);
    }
  }, [apiCall, pagination.page, pagination.limit]);

  const handlePageChange = useCallback((newPage) => {
    if (newPage >= 1 && newPage <= pagination.totalPages) {
      loadData(newPage, pagination.limit);
    }
  }, [loadData, pagination.limit, pagination.totalPages]);

  const handleLimitChange = useCallback((newLimit) => {
    loadData(1, newLimit);
  }, [loadData]);

  const refresh = useCallback(() => {
    loadData(pagination.page, pagination.limit);
  }, [loadData, pagination.page, pagination.limit]);

  // Carrega dados iniciais
  useEffect(() => {
    loadData();
  }, [loadData]);

  return {
    data,
    loading,
    error,
    pagination,
    handlePageChange,
    handleLimitChange,
    refresh,
    loadData
  };
}
